// Karşılama bölümünün e-posta mantığı: yazarken süzme, sakin doğrulama ve yazım düzeltme önerisi. Sayılar ABACUS'tandır.
// Kural: giris-alanlari-standardi.md (yazarken boşluk kırp ve küçük harfe çevir; kaydederken doğrulama motorunu çağır).
import { text, validate } from "@snn/abacus-core";
import { countText } from "../lib/shop-format";

/** E-posta yazarken süzme: boşluklar atılır, ASCII küçük harfe çevrilir (Türkçe büyük I küçük ı olmaz). */
export function cleanEmail(raw: string): string {
  return text.toAsciiLower(raw.replace(/\s+/g, ""));
}

/** Kaydetmeden önce doğrulama: belirli bir ileti ya da geçerliyse null. İlk yazılırken çağrılmaz (alandan çıkınca ya da gönderince). */
export function emailProblem(email: string): string | null {
  if (!email) return "E-posta adresinizi yazın.";
  if (!email.includes("@")) return "Adreste @ işareti eksik.";
  const [name, domain = ""] = email.split("@") as [string, string?];
  if (!name) return "@ işaretinden önce bir ad yazın.";
  if (!domain || !domain.includes(".") || domain.startsWith(".") || domain.endsWith(".")) return "Alan adı tamamlanmamış (örneğin ad@site.com).";
  return validate.email(email) ? null : "Geçerli bir e-posta adresi girin.";
}

/** Sık yapılan alan adı yazım hataları ve doğruları. */
const TYPOS: Record<string, string> = {
  "gmial.com": "gmail.com", "gamil.com": "gmail.com", "gnail.com": "gmail.com", "gmail.con": "gmail.com", "gmail.co": "gmail.com", "gmai.com": "gmail.com",
  "hotmial.com": "hotmail.com", "hotmai.com": "hotmail.com", "hotmail.con": "hotmail.com", "hotnail.com": "hotmail.com",
  "outlok.com": "outlook.com", "outloook.com": "outlook.com", "outlook.con": "outlook.com",
  "yahooo.com": "yahoo.com", "yaho.com": "yahoo.com", "yahoo.con": "yahoo.com",
  "icloud.con": "icloud.com", "iclod.com": "icloud.com",
};

/** Bilinen bir yazım hatası varsa düzeltilmiş adresi döndürür, yoksa null. */
export function suggestEmail(email: string): string | null {
  const at = email.lastIndexOf("@");
  if (at < 1) return null;
  const fixed = TYPOS[email.slice(at + 1)];
  return fixed ? `${email.slice(0, at)}@${fixed}` : null;
}

export const suggestionText = (suggestion: string): string => `Şunu mu demek istediniz: ${suggestion}?`;
export const peopleText = (count: number): string => `${countText(count)} kişi listede`;
export const rankSentence = (position: number): string => `Listede ${countText(position)}. sıradasınız`;
export const SUBMIT_LABELS = { full: "Listeye katıl", short: "Katıl", busy: "Gönderiliyor", retry: "Tekrar dene" } as const;

.root { container-type: inline-size; position: relative; isolation: isolate; display: grid; grid-template-columns: minmax(0, 1fr); place-items: center; overflow: hidden; padding: var(--space-8) var(--space-4); background: var(--background); color: var(--foreground); }
.mesh { position: absolute; inset: -20%; z-index: -1; background:
  radial-gradient(40% 40% at 25% 30%, color-mix(in oklch, var(--accent) 22%, transparent), transparent 70%),
  radial-gradient(35% 45% at 75% 25%, color-mix(in oklch, var(--accent) 12%, var(--neutral-5)), transparent 70%),
  radial-gradient(45% 40% at 60% 80%, color-mix(in oklch, var(--accent) 16%, transparent), transparent 70%),
  radial-gradient(30% 35% at 20% 80%, color-mix(in oklch, var(--success) 8%, transparent), transparent 70%);
  background-size: 140% 140%; animation: drift 38s ease-in-out infinite alternate; }
@keyframes drift { 0% { background-position: 0% 0%; transform: rotate(0deg) scale(1); } 50% { background-position: 60% 40%; transform: rotate(2deg) scale(1.05); } 100% { background-position: 0% 0%; transform: rotate(0deg) scale(1); } }
.mesh[data-paused] { animation-play-state: paused; }
.content { min-width: 0; display: grid; grid-template-columns: minmax(0, 1fr); justify-items: center; gap: var(--space-5); width: min(100%, 38rem); text-align: center; }
.title { margin: 0; font-family: var(--font-display); font-size: clamp(var(--text-3xl), 7cqw + 1rem, var(--text-5xl)); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); text-wrap: balance; }
.wordMask { display: inline-block; overflow: hidden; vertical-align: top; padding-bottom: .1em; }
.word { display: inline-block; }
.subline { margin: 0; max-width: 32rem; color: var(--text-secondary); font-size: var(--text-lg); text-wrap: balance; }
.formWrap { width: 100%; min-height: 6.5rem; }
.form { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-2); }
.field { transition: border-color var(--duration-fast) var(--ease-standard), box-shadow var(--duration-standard) var(--ease-standard); box-shadow: var(--shadow-resting); display: flex; gap: var(--space-2); align-items: stretch; padding: var(--space-1); border: 1px solid var(--border-strong); border-radius: var(--radius-pill); background: color-mix(in oklch, var(--surface) 88%, transparent); backdrop-filter: blur(10px); }
.field:hover { border-color: var(--neutral-6); box-shadow: var(--shadow-raised); }
.field:focus-within { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; }
.field input { flex: 1; min-width: 0; min-height: 2.75rem; padding: 0 var(--space-4); border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--foreground); font: inherit; font-size: max(16px, var(--text-base)); outline: none; }
.field input[aria-invalid="true"] { color: var(--danger); }
.submit { flex: none; min-height: 2.75rem; border-radius: var(--radius-pill); }
.label { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); }
.note { min-height: 1.5rem; margin: 0; color: var(--text-secondary); font-size: var(--text-sm); }
.note[data-tone="error"] { color: var(--danger); }
.link { padding: 0; border: 0; background: none; color: var(--accent-strong); font: inherit; text-decoration: underline; cursor: pointer; min-height: 1.5rem; }
.link:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; border-radius: 2px; }
.done { display: grid; justify-items: center; gap: var(--space-2); padding: var(--space-4); border-radius: var(--radius-panel); background: color-mix(in oklch, var(--accent) 14%, var(--surface)); outline: none; }
.rank { margin: 0; font-size: var(--text-xl); }
.rank b { font-family: var(--font-display); font-size: var(--text-3xl); font-weight: 500; font-variant-numeric: tabular-nums; }
.proof { padding-top: var(--space-2); display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: var(--space-3); color: var(--text-secondary); font-size: var(--text-sm); }
.faces { display: inline-flex; }
.faces > * { margin-left: -.625rem; box-shadow: 0 0 0 2px var(--background); border-radius: 50%; }
.faces > *:first-child { margin-left: 0; }
.count { font-variant-numeric: tabular-nums; }
.count span[class*="counter"] { font-size: var(--text-xl); vertical-align: middle; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.root[data-reduced] .mesh { animation: none; }
.root[data-reduced] .field { transition: none; }
@media (prefers-reduced-motion: reduce) { .mesh { animation: none; } .field { transition: none; } }
@media (max-width: 420px) { .proof { flex-direction: column; } }

"use client";

import { Fragment, useEffect, useId, useRef, useState, type FormEvent } from "react";
import { AnimatePresence, animate, motion } from "motion/react";
import { AnimatedCounter } from "../animated-counter/animated-counter";
import { Avatar } from "../avatar/avatar";
import { Button } from "../button/button";
import { motionTokens } from "../lib/motion-tokens";
import { useElementWidth, useOnScreen, useReducedMotionSafe } from "../lib/viz-utils";
import { SUBMIT_LABELS, cleanEmail, emailProblem, peopleText, rankSentence, suggestEmail, suggestionText } from "./hero-signup-format";
import styles from "./hero-signup.module.css";

export type SignupStatus = "idle" | "sending" | "error" | "done";

/** Açılış sayfasında tek e-posta alanıyla bekleme listesi ya da erken erişim toplamak için kullanın: akan renk geçişli arka plan, kelime kelime gelen başlık, sakin doğrulama (alandan çıkınca), yazım düzeltme önerisi ve gönderince "listedeki sıran" onayına dönüşen düğme. Parolalı kayıt, SSO ve bülten kutusu için değil; kaydı saklayan servisi `onSubmit` ile uygulama bağlar. */
export interface HeroSignupProps {
  headline: string;
  subline?: string | undefined;
  /** Alt not satırındaki sakin güvence cümlesi. */
  note?: string | undefined;
  /** Listeye eklemeyi yapar ve sırayı döndürür; reddederse "Yerinizi kaydedemedik." yazılır. */
  onSubmit: (email: string) => Promise<{ position: number }>;
  /** Listedeki kişi sayısı; katılınca bir artar. */
  count?: number | undefined;
  /** Sosyal kanıt portreleri için adlar (en çok beş). */
  people?: string[] | undefined;
  /** `people` ile aynı sırada portre adresleri; verilmeyenler baş harfli görünür. */
  peopleImages?: string[] | undefined;
  onStatusChange?: ((status: SignupStatus) => void) | undefined;
  /** Bölümün en az yüksekliği; varsayılan ekran yüksekliğidir. */
  minHeight?: string | undefined;
}

export function HeroSignup({ headline, subline, note = "Davetiniz hazır olunca tek e-posta alırsınız.", onSubmit, count, people = [], peopleImages = [], onStatusChange, minHeight = "100svh" }: HeroSignupProps) {
  const reduced = useReducedMotionSafe();
  const uid = useId();
  const [box, width] = useElementWidth<HTMLElement>();
  const [screen, onScreen] = useOnScreen<HTMLDivElement>();
  const input = useRef<HTMLInputElement>(null);
  const field = useRef<HTMLDivElement>(null);
  const done = useRef<HTMLDivElement>(null);
  const [email, setEmail] = useState("");
  const [touched, setTouched] = useState(false);
  const [status, setStatusState] = useState<SignupStatus>("idle");
  const [position, setPosition] = useState(0);
  const [failed, setFailed] = useState(false);
  const setStatus = (next: SignupStatus) => { setStatusState(next); onStatusChange?.(next); };

  const problem = touched ? emailProblem(email) : null;
  const suggestion = suggestEmail(email);
  const compact = width > 0 && width < 420;
  const words = headline.split(" ");
  const liveText = status === "sending" ? "Gönderiliyor" : status === "done" ? rankSentence(position) : status === "error" ? "Yerinizi kaydedemedik. Tekrar deneyebilirsiniz." : "";

  useEffect(() => { if (status === "done") done.current?.focus(); }, [status]);

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    if (status === "sending") return;
    setTouched(true);
    const found = emailProblem(email);
    if (found) { input.current?.focus(); if (!reduced && field.current) animate(field.current, { x: [0, -6, 6, -4, 4, 0] }, { duration: .35 }); return; }
    setStatus("sending"); setFailed(false);
    try { const result = await onSubmit(email); setPosition(result.position); setStatus("done"); }
    catch { setFailed(true); setStatus("error"); if (!reduced && field.current) animate(field.current, { x: [0, -6, 6, -4, 4, 0] }, { duration: .35 }); }
  };
  const change = () => { setStatus("idle"); setTouched(false); requestAnimationFrame(() => input.current?.focus()); };

  const rise = (delay: number) => reduced ? {} : { initial: { opacity: 0, y: 14, filter: "blur(4px)" }, animate: { opacity: 1, y: 0, filter: "blur(0px)" }, transition: { duration: motionTokens.duration.considered, ease: [...motionTokens.ease.enter] as [number, number, number, number], delay } };
  const total = (count ?? 0) + (status === "done" ? 1 : 0);

  return <section ref={box} className={styles.root} style={{ minHeight }} aria-labelledby={`${uid}-title`} data-reduced={reduced || undefined}>
    <div ref={screen} className={styles.mesh} data-paused={!onScreen || undefined} aria-hidden="true" />
    <div className={styles.content}>
      <h1 id={`${uid}-title`} className={styles.title}>{words.map((word, at) => <Fragment key={at}><span className={styles.wordMask}><motion.span className={styles.word} {...rise(at * motionTokens.stagger.word)}>{word}</motion.span></span>{at < words.length - 1 ? " " : ""}</Fragment>)}</h1>
      {subline && <motion.p className={styles.subline} {...rise(words.length * motionTokens.stagger.word + .1)}>{subline}</motion.p>}
      <motion.div className={styles.formWrap} {...rise(words.length * motionTokens.stagger.word + .2)}>
        <AnimatePresence mode="wait" initial={false}>
          {status === "done" ? <motion.div key="done" ref={done} tabIndex={-1} className={styles.done} initial={reduced ? false : { opacity: 0, scale: .94 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }} transition={reduced ? { duration: 0 } : motionTokens.spring.morph}>
            <p className={styles.rank}><span>Listede</span> <b><AnimatedCounter value={position} /></b><span>. sıradasınız</span></p>
            <button type="button" className={styles.link} onClick={change}>E-postayı değiştir</button>
          </motion.div>
            : <motion.form key="form" className={styles.form} onSubmit={submit} noValidate initial={false} exit={{ opacity: 0 }} transition={{ duration: reduced ? 0 : motionTokens.duration.fast }}>
              <div ref={field} className={styles.field}>
                <label htmlFor={`${uid}-email`} className={styles.label}>E-posta adresi</label>
                <input ref={input} id={`${uid}-email`} name="email" type="email" inputMode="email" autoComplete="email" enterKeyHint="send" placeholder="E-posta adresi" value={email}
                  aria-invalid={!!problem || undefined} aria-describedby={`${uid}-note`} onChange={event => { setEmail(cleanEmail(event.target.value)); if (status === "error") setStatus("idle"); }} onBlur={() => { if (email) setTouched(true); }} />
                <Button type="submit" variant="primary" size="lg" className={styles.submit} loading={status === "sending"} aria-busy={status === "sending"}>{status === "sending" ? SUBMIT_LABELS.busy : compact ? SUBMIT_LABELS.short : SUBMIT_LABELS.full}</Button>
              </div>
              <p id={`${uid}-note`} className={styles.note} data-tone={problem || failed ? "error" : undefined}>
                {problem ?? (failed ? <>Yerinizi kaydedemedik. <button type="submit" className={styles.link}>{SUBMIT_LABELS.retry}</button></> : suggestion ? <>{suggestionText(suggestion)} <button type="button" className={styles.link} onClick={() => { setEmail(suggestion); input.current?.focus(); }}>Düzelt</button></> : note)}
              </p>
            </motion.form>}
        </AnimatePresence>
      </motion.div>
      {(people.length > 0 || count !== undefined) && <motion.div className={styles.proof} {...rise(words.length * motionTokens.stagger.word + .3)}>
        {people.length > 0 && <span className={styles.faces} aria-hidden="true">{people.slice(0, 5).map((name, at) => <Avatar key={name} name={name} src={peopleImages[at]} size="md" />)}</span>}
        {count !== undefined && <span className={styles.count}><span className={styles.srOnly}>{peopleText(total)}</span><span aria-hidden="true"><AnimatedCounter value={total} /> kişi listede</span></span>}
      </motion.div>}
    </div>
    <div className={styles.srOnly} role="status" aria-live="polite" aria-atomic="true">{liveText}</div>
  </section>;
}

export default HeroSignup;
